def _attribution_map(tx: pd.DataFrame, cache_dir: str | Path | None = None) -> pd.DataFrame:
    """Map every line to the date its activity should be counted against.

    Returns [_line_id, Invoice, StockCode, customer_id, InvoiceDate, is_credit, eff_date].
    `eff_date` is NaT for credits that cannot be attributed to any prior order.

    Memoised under the cache directory, keyed by a fingerprint of the attribution logic
    version *and* the panel contents.  Any cache that does not match that fingerprint --
    including one written by the older document-date attribution -- is discarded and
    rebuilt rather than reused.
    """
    cdir = _cache_dir(cache_dir)
    fingerprint = _panel_fingerprint(tx)
    cached = _cache_path(cdir, fingerprint)

    _purge_stale(cdir, keep=cached)

    if cached.exists():
        try:
            amap = pd.read_parquet(cached)
        except (OSError, ValueError):
            amap = None
        if amap is not None and _cache_is_valid(amap, tx):
            return amap
        try:
            cached.unlink()
        except OSError:
            pass

    amap = _resolve(tx)
    try:
        cdir.mkdir(parents=True, exist_ok=True)
        amap.to_parquet(cached, index=False)
    except OSError:
        pass
    return amap


def _cache_is_valid(amap: pd.DataFrame, tx: pd.DataFrame) -> bool:
    """Structural check that a cached map really came from the current logic."""
    required = {LINE_ID, "Invoice", "StockCode", "customer_id",
                "InvoiceDate", "is_credit", "eff_date"}
    if not required.issubset(amap.columns) or len(amap) != len(tx):
        return False
    if not amap[LINE_ID].equals(tx[LINE_ID]):
        return False
    # Under current logic every unmatched credit is NaT and no order line is ever NaT.
    orders = ~amap["is_credit"].astype(bool)
    if amap.loc[orders, "eff_date"].isna().any():
        return False
    if not amap.loc[orders, "eff_date"].reset_index(drop=True).equals(
            tx.loc[orders.to_numpy(), "InvoiceDate"].reset_index(drop=True)):
        return False
    credits = amap["is_credit"].astype(bool)
    if credits.any():
        cr = amap.loc[credits]
        # A credit must never be attributed to its own (or a later) document date.
        if (cr["eff_date"].notna() & (cr["eff_date"] >= cr["InvoiceDate"])).any():
            return False
    return True


def build_features(tx: pd.DataFrame,
                   probes: pd.DataFrame,
                   cache_dir: str | Path | None = None) -> pd.DataFrame:
    """Trailing-window features for each (customer_id, as_of) row of `probes`.

    Returns an integer frame indexed by (customer_id, as_of) with FEATURE_COLUMNS.
    """
    tx = _prepare(tx)
    amap = _attribution_map(tx, cache_dir)

    tx = tx.merge(amap[[LINE_ID, "eff_date"]], on=LINE_ID, how="left")
    tx["revenue"] = tx["Quantity"] * tx["Price"]

